const items = $input.all();
const pdfItems = [];

for (const item of items) {
  const bin = item.binary || {};
  const headers = item.json.payload?.headers || [];
  const subjectHeader = headers.find((h) => h.name && h.name.toLowerCase() === 'subject');
  const fromHeader = headers.find((h) => h.name && h.name.toLowerCase() === 'from');
  const dateHeader = headers.find((h) => h.name && h.name.toLowerCase() === 'date');

  const emailSubject = item.json.subject || (subjectHeader ? subjectHeader.value : 'Email có đính kèm PDF');
  const senderEmail = (item.json.from && item.json.from.value && item.json.from.value[0] && item.json.from.value[0].address) || (fromHeader ? fromHeader.value : 'email@attech.com.vn');
  const receivedDate = item.json.date
    ? String(item.json.date).slice(0, 16).replace('T', ' ')
    : (dateHeader ? dateHeader.value : new Date().toISOString().slice(0, 16).replace('T', ' '));

  for (const key of Object.keys(bin)) {
    const att = bin[key];
    const fileName = att.fileName || 'tai_lieu_email.pdf';
    const isPdf = att.mimeType === 'application/pdf' || fileName.toLowerCase().endsWith('.pdf');

    if (isPdf) {
      pdfItems.push({
        json: {
          hasPdf: true,
          emailSubject,
          senderEmail,
          receivedDate,
          pdfFileName: fileName,
          extractedTitle: fileName.replace(/\.pdf$/i, '').replace(/[_-]+/g, ' ').trim(),
        },
        binary: {
          file: att,
        },
      });
    }
  }
}

if (pdfItems.length === 0) {
  return [{ json: { hasPdf: false, items: [] } }];
}

return pdfItems;

const uploaded = $input.all();
const sourceItems = $('3. Lọc riêng các file PDF đính kèm').all();

const resultItems = uploaded.map((u, idx) => {
  const src = (sourceItems[idx] && sourceItems[idx].json) ? sourceItems[idx].json : {};
  return {
    emailSubject: src.emailSubject || u.json.name || 'Email đính kèm PDF',
    senderEmail: src.senderEmail || 'email@attech.com.vn',
    receivedDate: src.receivedDate || new Date().toISOString().slice(0, 16).replace('T', ' '),
    pdfFileName: u.json.name || src.pdfFileName || 'document.pdf',
    extractedTitle: src.extractedTitle || String(u.json.name || '').replace(/\.pdf$/i, ''),
    driveFileId: u.json.id || '',
    fileUrl: u.json.webViewLink || (u.json.id ? 'https://drive.google.com/file/d/' + u.json.id + '/view' : ''),
    driveFolderName: 'ATTECH_DOCUMENTS/03_TÀI LIỆU CHƯA XÁC THỰC',
  };
});

return [{ json: { success: true, count: resultItems.length, items: resultItems } }];
